CREATE TABLE public.growth_goals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 200), objective text NOT NULL DEFAULT 'revenue' CHECK(objective IN ('revenue','leads','customers','reservations','online_sales','retention','launch','new_market','awareness','cac','repeat_purchases','other')), priority text NOT NULL DEFAULT 'secondary' CHECK(priority IN ('primary','secondary')), metric text NOT NULL DEFAULT '' CHECK(length(metric)<=120), baseline numeric CHECK(baseline IS NULL OR baseline>=0), target numeric CHECK(target IS NULL OR target>=0), current_value numeric CHECK(current_value IS NULL OR current_value>=0), due_date date, rationale text NOT NULL DEFAULT '' CHECK(length(rationale)<=2000), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','achieved','paused','archived')), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,org_id,workspace_id));
GRANT SELECT, INSERT, UPDATE ON public.growth_goals TO authenticated; GRANT ALL ON public.growth_goals TO service_role;
ALTER TABLE public.growth_goals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.budget_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), workspace_id uuid NOT NULL REFERENCES public.workspaces(id), channel text NOT NULL CHECK(length(trim(channel)) BETWEEN 1 AND 80), period_month date NOT NULL CHECK(extract(day from period_month)=1), planned numeric NOT NULL DEFAULT 0 CHECK(planned>=0), actual numeric NOT NULL DEFAULT 0 CHECK(actual>=0), hard_cap numeric CHECK(hard_cap IS NULL OR hard_cap>=0), currency text NOT NULL DEFAULT 'EUR' CHECK(currency ~ '^[A-Z]{3}$'), goal_id uuid, note text NOT NULL DEFAULT '' CHECK(length(note)<=500), created_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(hard_cap IS NULL OR planned<=hard_cap), FOREIGN KEY(goal_id,org_id,workspace_id) REFERENCES public.growth_goals(id,org_id,workspace_id));
GRANT SELECT, INSERT, UPDATE ON public.budget_lines TO authenticated; GRANT ALL ON public.budget_lines TO service_role;
ALTER TABLE public.budget_lines ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['growth_goals','budget_lines'] LOOP
 EXECUTE format('CREATE POLICY growth_read ON public.%I FOR SELECT TO authenticated USING(public.has_workspace_role(workspace_id,''viewer''))',t);
 EXECUTE format('CREATE POLICY growth_create ON public.%I FOR INSERT TO authenticated WITH CHECK(public.has_workspace_role(workspace_id,''member'') AND created_by=auth.uid())',t);
 EXECUTE format('CREATE POLICY growth_update ON public.%I FOR UPDATE TO authenticated USING(public.has_workspace_role(workspace_id,''member'')) WITH CHECK(public.has_workspace_role(workspace_id,''member''))',t);
 EXECUTE format('CREATE TRIGGER growth_scope_guard BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_content_scope()',t);
END LOOP; END $$;